import { useState } from "react";
import { checkAssessment } from "../api";

export default function AssessmentPage({ course, questions, setResult, setStage }) {
  const [answers, setAnswers] = useState([]);

  async function handleSubmit() {
    // Navigate immediately to video to avoid any flicker/delay
    setStage("video");
    try {
      const data = await checkAssessment(course, answers);
      setResult(data.result);
    } catch (e) {
      console.error(e);
      setResult("error");
    }
  }

  const renderedQuestions =
    typeof questions === "string"
      ? questions
      : Array.isArray(questions)
      ? questions.join("\n")
      : JSON.stringify(questions, null, 2);

  return (
    <div>
      <h2>Assessment for {course}</h2>
      <pre>{renderedQuestions}</pre>
      <button onClick={handleSubmit}>Submit Assessment</button>
    </div>
  );
}
